∀ {Identity Payload : Type} {retainedRun : Identity → Prop} {commitPayload : Payload → Identity}
  {ledger : SearchRouteAdmissionHistory.CommitmentLedger Identity}
  {store : SearchRouteAdmissionRetention.ReceiptStore Identity Payload} {runIdentity : Identity}
  {record : SearchRouteAdmissionHistory.AdmissionRecord Identity},
  SearchRouteAdmissionRetention.RetentionInvariant retainedRun commitPayload ledger store →
    retainedRun runIdentity →
      SearchRouteAdmissionHistory.CommittedRecord ledger runIdentity record →
        SearchRouteAdmissionRetention.AcknowledgementRecoverable commitPayload ledger store runIdentity

∀ {Identity Payload : Type} {retainedRun : Identity → Prop} {commitPayload : Payload → Identity}
  {ledger : SearchRouteAdmissionHistory.CommitmentLedger Identity}
  {before after : SearchRouteAdmissionRetention.ReceiptStore Identity Payload} {runIdentity : Identity}
  {record : SearchRouteAdmissionHistory.AdmissionRecord Identity},
  SearchRouteAdmissionRetention.SafeGarbageCollection retainedRun ledger before after →
    retainedRun runIdentity →
      SearchRouteAdmissionHistory.CommittedRecord ledger runIdentity record →
        SearchRouteAdmissionRetention.RecordResolvable commitPayload before record →
          SearchRouteAdmissionRetention.RecordResolvable commitPayload after record

∀ {Identity Payload : Type} {retainedRun : Identity → Prop} {commitPayload : Payload → Identity}
  {ledger : SearchRouteAdmissionHistory.CommitmentLedger Identity}
  {before after : SearchRouteAdmissionRetention.ReceiptStore Identity Payload},
  SearchRouteAdmissionRetention.RetentionInvariant retainedRun commitPayload ledger before →
    SearchRouteAdmissionRetention.SafeGarbageCollection retainedRun ledger before after →
      SearchRouteAdmissionRetention.RetentionInvariant retainedRun commitPayload ledger after
